settings.customCss:
/* MegaForm Gen-3 scroll-aware single-page shell: realestate-registration */
.mfp.mfp-realestate-registration{--rey-page:#f0ebe0;--rey-paper:#fffcf5;--rey-ink:#1c1c1e;--rey-muted:#8a8a8f;--rey-line:#e5e0d8;--rey-input:#fff;--rey-primary:#e8881a;--rey-soft:#fff3e0;--rey-error:#c0392b;--rey-font:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;--rey-display:"Bricolage Grotesque",Inter,system-ui,sans-serif;--mf-btn-bg:var(--rey-primary);display:block!important;width:100%!important;max-width:720px!important;margin:0 auto!important;color:var(--rey-ink);font-family:var(--rey-font)}
.mfp.mfp-realestate-registration,.mfp.mfp-realestate-registration *,.mfp.mfp-realestate-registration *::before,.mfp.mfp-realestate-registration *::after{box-sizing:border-box}
.mf-form-wrapper .mf-form-inner .mfp.mfp-realestate-registration{display:block!important;width:100%!important;max-width:720px!important;margin-inline:auto!important}
.mfp-realestate-registration .mfp-stage{width:100%;max-width:720px!important;margin-inline:auto!important;padding:0;border:0;border-radius:0;background:transparent}
.mfp-realestate-registration .mfp-paper{position:relative;width:100%;max-width:720px!important;margin:0 auto!important;background:var(--rey-paper);box-shadow:0 20px 45px rgba(40,31,20,.14)}
.mfp-realestate-registration .mfp-body{position:relative;padding:12px 32px 36px}
.mfp-realestate-registration .mfp-section-head{display:flex;align-items:center;gap:11px;margin:26px 0 16px}.mfp-realestate-registration .mfp-section-head h2{margin:0;color:var(--rey-ink);font-size:12px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.mfp-realestate-registration .mfp-section-head>span:last-child{height:1px;flex:1;background:var(--rey-line)}
.mfp-realestate-registration .mfp-section-icon{display:grid;width:30px;height:30px;flex:0 0 auto;place-items:center;border-radius:8px;background:var(--rey-soft);color:var(--rey-primary);font-size:14px;font-weight:900}
.mfp-realestate-registration .mfp-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 20px}.mfp-realestate-registration .mfp-stack{display:grid;gap:16px}.mfp-realestate-registration .mfp-wide{margin-top:16px}.mfp-realestate-registration .mf-field-group{min-width:0;margin:0}
.mfp-realestate-registration .mf-field-label{display:block;margin:0 0 6px;color:var(--rey-muted);font-size:10px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.mfp-realestate-registration .mf-required{color:var(--rey-error)}
.mfp-realestate-registration .mf-input,.mfp-realestate-registration .mf-select,.mfp-realestate-registration .mf-textarea,.mfp-realestate-registration input:not([type='checkbox']):not([type='radio']),.mfp-realestate-registration select,.mfp-realestate-registration textarea{width:100%!important;min-height:43px!important;padding:9px 12px!important;border:1px solid var(--rey-line)!important;border-radius:8px!important;outline:0!important;background:var(--rey-input)!important;color:var(--rey-ink)!important;box-shadow:none!important;font:inherit!important;font-size:14px!important}
.mfp-realestate-registration .mf-textarea,.mfp-realestate-registration textarea{min-height:112px!important;resize:vertical!important}.mfp-realestate-registration .mf-input:focus,.mfp-realestate-registration .mf-select:focus,.mfp-realestate-registration .mf-textarea:focus,.mfp-realestate-registration input:focus,.mfp-realestate-registration select:focus,.mfp-realestate-registration textarea:focus{border-color:var(--rey-primary)!important;box-shadow:0 0 0 3px color-mix(in srgb,var(--rey-primary) 14%,transparent)!important}
.mfp-realestate-registration input::placeholder,.mfp-realestate-registration textarea::placeholder{color:color-mix(in srgb,var(--rey-muted) 58%,transparent)}.mfp-realestate-registration .mf-field-error{margin-top:5px;color:var(--rey-error);font-size:11px}
.mfp-realestate-registration .mfp-chip .mf-option-group{display:flex!important;flex-wrap:wrap!important;gap:8px!important;grid-template-columns:none!important}.mfp-realestate-registration .mfp-chip .mf-option-item{display:inline-flex!important;width:auto!important;margin:0!important;padding:0!important}.mfp-realestate-registration .mfp-chip .mf-option-control{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;clip-path:inset(50%)!important}
.mfp-realestate-registration .mfp-chip .mf-option-ui{display:inline-flex!important;min-height:32px!important;align-items:center!important;padding:7px 12px!important;border:1px solid var(--rey-line)!important;border-radius:999px!important;background:var(--rey-input)!important;color:var(--rey-muted)!important;box-shadow:none!important}.mfp-realestate-registration .mfp-chip .mf-option-label{color:inherit!important;font-size:12px!important;font-weight:700!important}.mfp-realestate-registration .mfp-chip .mf-option-control:checked + .mf-option-ui{border-color:var(--rey-primary)!important;background:var(--rey-soft)!important;color:var(--rey-primary)!important}
.mfp-realestate-registration .mfp-check .mf-option-group{display:block!important}.mfp-realestate-registration .mfp-check .mf-option-item{display:flex!important;align-items:flex-start!important;gap:9px!important;margin:0!important;padding:0!important}.mfp-realestate-registration .mfp-check .mf-option-control{position:static!important;width:17px!important;height:17px!important;margin:3px 0 0!important;accent-color:var(--rey-primary)!important;opacity:1!important}.mfp-realestate-registration .mfp-check .mf-option-ui{display:block!important;padding:0!important;border:0!important;background:transparent!important;color:var(--rey-muted)!important}.mfp-realestate-registration .mfp-check .mf-option-label{color:inherit!important;font-size:13px!important;line-height:1.5!important}
.mfp-realestate-registration .mfp-actions{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:26px;padding-top:22px;border-top:1px solid var(--rey-line);color:var(--rey-muted);font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.mfp-realestate-registration .mfp-btn{display:inline-flex;min-height:44px;align-items:center;justify-content:center;gap:8px;border:0;border-radius:999px;padding:11px 22px;background:var(--rey-primary)!important;color:#fff!important;font:inherit;font-size:12px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;cursor:pointer}
.mfp-realestate-registration .mfp-hidden{display:none!important}.mfp-realestate-registration .mf-form-title,.mfp-realestate-registration .mf-form-description,.mfp-realestate-registration .mf-success-message,.mfp-realestate-registration .mf-form-actions{display:none!important}.mf-form-wrapper:has(.mfp-realestate-registration){--mf-page-bg:transparent!important;--mf-form-bg:transparent!important;--mf-card-bg:transparent!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;background:transparent!important;background-image:none!important;box-shadow:none!important}.mf-form-wrapper:has(.mfp-realestate-registration) .mf-form,.mf-form-wrapper:has(.mfp-realestate-registration) .mf-form-inner{width:100%!important;max-width:none!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important}.mf-form-wrapper:has(.mfp-realestate-registration) .mf-form-actions{display:none!important}
@media(max-width:700px){.mfp-realestate-registration .mfp-body{padding:8px 20px 28px}.mfp-realestate-registration .mfp-row{grid-template-columns:1fr;gap:15px}}
@media(max-width:440px){.mfp-realestate-registration .mfp-body{padding:6px 16px 24px}.mfp-realestate-registration .mfp-actions{align-items:stretch;flex-direction:column-reverse}.mfp-realestate-registration .mfp-btn{width:100%}}

.mfp-realestate-registration .mfp-paper{overflow:hidden;border-radius:20px}.mfp-realestate-registration .mfp-header{position:relative;overflow:hidden;border-radius:20px 20px 0 0;background:#f5a130;color:#fff}.mfp-realestate-registration .mfp-art{position:absolute;inset:0;background:url('/Modules/MegaForm/Assets/img/realestate-registration/header-illus.png') center/cover;opacity:.24;mix-blend-mode:overlay}.DnnModule .mfp-realestate-registration .mfp-art{background-image:url('/DesktopModules/MegaForm/Assets/img/realestate-registration/header-illus.png')}
.mfp-realestate-registration .mfp-header-copy{position:relative;z-index:1;display:flex;justify-content:space-between;gap:24px;padding:28px 32px 8px}.mfp-realestate-registration .mfp-brand{margin:0 0 6px;color:rgba(255,255,255,.82);font-size:10px;font-weight:900;letter-spacing:.18em;text-transform:uppercase}.mfp-realestate-registration .mfp-header h1{margin:0;color:#fff;font-family:var(--rey-display);font-size:30px;font-weight:900}.mfp-realestate-registration .mfp-header-copy p:last-child{margin:6px 0 0;color:rgba(255,255,255,.76);font-size:13px}
.mfp-realestate-registration .mfp-date{border-radius:12px;padding:9px 14px;background:rgba(255,255,255,.18);text-align:right}.mfp-realestate-registration .mfp-date small{display:block;font-size:9px;text-transform:uppercase}.mfp-realestate-registration .mfp-date strong{font-size:13px}.mfp-realestate-registration .mfp-contact{position:relative;z-index:1;display:flex;flex-wrap:wrap;gap:7px 22px;padding:7px 32px 14px;color:rgba(255,255,255,.82);font-size:11px}.mfp-realestate-registration .mfp-wave{position:relative;z-index:1;display:block;width:100%;height:38px;margin-bottom:-1px}.mfp-realestate-registration .mfp-wave path{fill:var(--rey-paper)}
.mfp-realestate-registration .mfp-foot{display:flex;justify-content:space-between;gap:12px;padding:14px 32px 20px;color:var(--rey-muted);font-size:10px}@media(max-width:540px){.mfp-realestate-registration .mfp-header-copy{padding-inline:20px}.mfp-realestate-registration .mfp-date{display:none}.mfp-realestate-registration .mfp-contact{padding-inline:20px}.mfp-realestate-registration .mfp-foot{flex-direction:column;align-items:center}}
